#include <iostream>
#include <iomanip>
#include <cstdint>

int main() {
    int periods = 0;
    if (!(std::cin >> periods)) {
        return 0;
    }

    std::uint64_t base_transistors = 2300; // Intel 4004 (1971)
    std::cout << "Period | Transistor Count\n";
    std::cout << "-------+-----------------\n";

    std::uint64_t current = base_transistors;
    for (int i = 0; i <= periods; ++i) {
        std::cout << std::setw(6) << i << " | "
                  << std::setw(15) << current << '\n';
        current *= 2;
    }

    return 0;
}

#include <iostream>
#include <string>

// Mô phỏng dòng dữ liệu qua các khối logic:
// 1. Input: Nhận hai số nguyên từ luồng vào
// 2. Memory: Lưu trữ dữ liệu trong biến (RAM volatile)
// 3. ALU: Tính toán và kiểm tra điều kiện logic
// 4. Output: Xuất kết quả ra luồng chuẩn (cout)

int main() {
    // Input unit & Memory allocation
    int operandA = 0;
    int operandB = 0;

    if (!(std::cin >> operandA >> operandB)) {
        return 0;
    }

    // ALU operations: Arithmetic
    int sum = operandA + operandB;
    int product = operandA * operandB;

    // ALU operations: Logical comparison
    bool isEqual = (operandA == operandB);

    // Output unit
    std::cout << "Sum: " << sum << '\n';
    std::cout << "Product: " << product << '\n';
    std::cout << "Equal: " << (isEqual ? "true" : "false") << '\n';

    return 0;
}
